"""Apply primary assessment/comparison corrections to the stable worker handoff."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'staging/route-control/lessons.json'
lessons=json.loads(p.read_text(encoding='utf-8'))
comparisons=[
 [['Import / export','Receiving candidate / outgoing advertisement','An export denial can preserve the local eligible BGP choice.'],['Route filter / packet ACL','Routing information / packet headers','Keep consuming feature, observer and direction explicit.'],['Policy definition / attachment','Named object / activated consumer','An unattached list does not govern the selected peer.']],
 [['Source protocol view / selected source RIB','Visible alternative / source selected for this boundary','A configured or visible route is not automatically redistributed.'],['Seed metric / administrative distance','Target protocol cost / local source preference','Neither is a universal conversion of the source metric.'],['Route tag / authenticated provenance','Administrative marker / independently established origin','A tag100 guard covers one declared feedback case only.']],
 [['Referenced-list deny / route-map deny','Entry nonmatch / matching entry rejection','Continue after nonmatch; reject after the fixed matching deny entry.'],['Match / set','Condition / attribute action','A set clause does not make a nonmatching entry match.'],['Simple default exits / advanced control','First matching permit or deny / call, goto or continue','This worksheet implements the simple fixed entry sets only.']],
 [['Containment / prefix length','Address interval / route specificity','Both must satisfy the selected entry.'],['Bare0/0 / 0/0 le32','Default route only / all IPv4 route lengths','The same base prefix does not imply the same policy scope.'],['Exact entry / ge-le range','One route length / inclusive length bounds','A contained child needs an explicit permitted length range.']],
 [['Wildcard / subnet mask','One means ignore / one means network significance','A noncontiguous wildcard cannot be replaced by a CIDR assumption.'],['Standard / extended packet ACL','Source only / source, destination and protocol-specific fields','The fixed TCP443 rule checks destination port as well as both addresses.'],['Stateless permit / established transaction','One header decision / application and reply state','A permit creates no route, reply policy or session state.']]
]
checks=[
 [('Import denial with Established still declared: what fails?','This imported candidate, while the independent session declaration can remain Established.','The filter applies to the supplied route rather than the TCP relationship.'),('What remains when only exportPermit becomes false?','The eligible selected local BGP candidate can remain; this outgoing advertisement is denied.','Outgoing policy is a separate boundary from local choice.'),('Why is a postpolicy BGP view not a complete unfiltered received-route history?','It reflects its declared observer/store and policy scope, not every original UPDATE or rejected candidate.','Name the actual view before interpreting absent information.')],
 [('Why does a configured but unselected source route fail this boundary?','The worksheet starts from a selected source-RIB route.','Configuration and protocol visibility are weaker than the required selection declaration.'),('Why is an equal source and target metric number not a conversion rule?','Each metric has protocol-specific meaning; the target requires its own seed design.','Identical integers do not make different protocol metrics equivalent.'),('What is the exact scope of rejecting source tag100?','It blocks this identified feedback marker, without proving universal loop prevention.','Tags can be rewritten or lost at other boundaries.')],
 [('A referenced prefix-list denies the route: does that route-map entry match?','No; this fixed prefix-list match condition returns nonmatch.','The model continues to another entry rather than applying the entry action.'),('A matching route-map deny precedes a later permit: which acts?','The matching deny rejects the route in this simple default-exit ruleset.','Later entries are not consulted after that match.'),('Does set LOCAL_PREF200 make a nonmatching entry match?','No; the match condition is independent of its set action.','Actions apply only under the consuming feature and matched entry semantics.')],
 [('Does bare198.51.100.0/24 match198.51.100.128/25?','No; without length qualifiers the route must have the exact /24 length.','Containment alone does not satisfy an exact entry.'),('Which child lengths pass ge25 le28 under the /24 base?','Contained aligned children /25 through /28 inclusive.','Both containment and inclusive lower/upper length bounds must agree.'),('How does bare0/0 differ from0/0 le32?','Bare0/0 matches only the default; le32 admits every aligned IPv4 route prefix.','Adding the upper qualifier changes specificity scope.')],
 [('Why does wildcard0.0.254.255 match an even third octet?','Its third-octet least significant bit is significant while the other third-octet bits are ignored.','Wildcard bit zero requires equality; the base third octet2 has low bit zero.'),('Does the fixed standard ACL inspect TCP destination port443?','No; it tests packet source only.','Extended rules can include transport fields, but this standard list does not.'),('Does a TCP443 packet permit create a return session?','No; this ACL is stateless and return/forwarding prerequisites are separate.','A single allowed header decision proves no complete application exchange.')]
]
for l,rows,qs in zip(lessons,comparisons,checks):
 l['comparison']=rows
 l['quick']=[dict(question=q,answer=a,explanation=e,type='short-answer',difficulty='Intermediate',testedConcept='Topic-specific boundary',topicId=l['id'],questionId=l['id']+'-QC'+str(i+1)) for i,(q,a,e) in enumerate(qs)]
 if l['id']=='s3-g5-t2':l['glossary']['Implicit deny']=l['glossary'].pop('Implicitdeny')
 if l['id']=='s3-g5-t4':
  l['glossary']['Standard ACL']=l['glossary'].pop('StandardACL');l['glossary']['Extended ACL']=l['glossary'].pop('ExtendedACL')
p.write_text(json.dumps(lessons,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Primary replaced15 generic quick checks and five comparison tables with topic-specific reviewed content.')
